fn rnd(x:f64)->i64{let z=x*1000.;if z>=0.{(z+0.5) as i64}else{-((-z+0.5) as i64)}}
#[no_mangle]
pub extern "C" fn liang_barsky(v:*const i64,n:usize)->i64{if n!=8||v.is_null(){return -1;}let a=unsafe{std::slice::from_raw_parts(v,n)};if a.iter().any(|&x|!(-5..=5).contains(&x)){return -1;}let(xmin,ymin,xmax,ymax,x0,y0,x1,y1)=(a[0]as f64,a[1]as f64,a[2]as f64,a[3]as f64,a[4]as f64,a[5]as f64,a[6]as f64,a[7]as f64);if xmin>=xmax||ymin>=ymax{return -1;}let dx=x1-x0;let dy=y1-y0;let p=[-dx,dx,-dy,dy];let q=[x0-xmin,xmax-x0,y0-ymin,ymax-y0];let(mut t0,mut t1)=(0.,1.);for i in 0..4{let t=q[i]/p[i];if p[i]==0.&&q[i]<0.{return -1;}else if p[i]<0.{if t>t1{return -1;}if t>t0{t0=t;}}else if p[i]>0.{if t<t0{return -1;}if t<t1{t1=t;}}}let z=[x0+t0*dx,y0+t0*dy,x0+t1*dx,y0+t1*dy];z.iter().fold(0i64,|r,&x|r*10001+rnd(x)+5000)}
